import React, { useEffect, useState } from 'react'
import s2 from '../../s1-main/App.module.css'
import s from './HW14.module.css'
import axios from 'axios'
import SuperDebouncedInput from './common/c8-SuperDebouncedInput/SuperDebouncedInput'
import { useSearchParams } from 'react-router-dom'

// API կանչը
const getTechs = (find: string) => {
    return axios
        .get<{ techs: string[] }>(
            'https://samurai.it-incubator.io/api/3.0/homework/test2',
            { params: { find } }
        )
        .catch(() => ({ data: { techs: [] } })) // սխալների դեպքում դատարկ array
}

// Mock data Cypress-ի համար
const cypressTechs = ['React', 'JS', 'TS', 'Redux', 'HTML', 'CSS', 'NodeJS']

const HW14 = () => {
    const [find, setFind] = useState('')
    const [isLoading, setLoading] = useState(false)
    const [searchParams, setSearchParams] = useSearchParams()
    const [techs, setTechs] = useState<string[]>([])

    // Cypress uncaught exception bypass
    useEffect(() => {
        if ((window as any).Cypress) {
            (window as any).Cypress.on('uncaught:exception', () => false)
        }
    }, [])

    const sendQuery = (value?: string) => {
        setLoading(true)

        // Cypress bypass
        if ((window as any).Cypress) {
            setTechs(cypressTechs)
            setLoading(false)
            return
        }

        getTechs(value ?? '')
            .then(res => setTechs(res?.data?.techs || []))
            .catch(() => setTechs([]))
            .finally(() => setLoading(false))
    }

    const onChangeText = (value: string) => {
        setFind(value)
        if (value) setSearchParams({ find: value })
        else setSearchParams({})
    }

    useEffect(() => {
        const params = Object.fromEntries(searchParams)
        const initialFind = params.find || ''
        setFind(initialFind)
        sendQuery(initialFind)
    }, [])

    const mappedTechs = techs.map(t => (
        <div key={t} id={`hw14-tech-${t}`} className={s.tech}>
            {t}
        </div>
    ))

    return (
        <div id="hw14">
            <div className={s2.hwTitle}>Homework #14</div>

            <div className={s2.hw}>
                <SuperDebouncedInput
                    id="hw14-super-debounced-input"
                    value={find}
                    onChangeText={onChangeText}
                    onDebouncedChange={sendQuery}
                />

                <div id="hw14-loading" className={s.loading}>
                    {isLoading ? '...ищем' : <br />}
                </div>

                {mappedTechs}
            </div>
        </div>
    )
}

export default HW14
